<script module lang="ts">
/**
 * The links between the sibling pages of one section, with the current page marked (`design/components/section-nav.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/section-nav.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import { agentMember, agentPress, joinSlot, watchEffect } from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/section-nav.module.css'

export interface SectionNavItem {
  label: string
  href: string
}

export interface SectionNavProps {
  /**
   * The `href` of the item whose page the reader is on; without it no item is current. It is
   * compared as the page it names, so a trailing slash, a query or a hash on either side does
   * not stop the match, and neither does an origin on `current` (`location.href`).
   */
  current?: string
  /**
   * One link per sibling page, in the order drawn.
   */
  items: SectionNavItem[]
  /**
   * The landmark's accessible name, which tells this navigation from the page's others.
   */
  label: string
  /**
   * The app's router, for every item (`link.md` §Routing): a click that would navigate this tab
   * calls it in place of the browser.
   */
  onNavigate?: (href: string) => void
}
</script>

<script lang="ts">
let { current, items, label: labelOwn, onNavigate }: SectionNavProps = $props()
const joined = joinSlot(undefined, () => ({ label: labelOwn }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
const listening = {
  get navigate() {
    return onNavigate !== undefined
  },
}
let root = $state<HTMLElement | null>(null)
const originOf = $derived((href: string): string | undefined =>
  /^(?:[a-z][a-z\d+.-]*:)?\/\/[^/?#]*/iu.exec(href)?.[0].toLowerCase(),
)
const pageOf = $derived((href: string): string => {
  if (href.startsWith('#') || href.startsWith('?')) return href
  const origin = originOf(href) ?? ''
  const path = href.slice(origin.length).replace(/[?#].*$/u, '')
  if (path === '') return origin === '' ? '' : '/'
  return path.length > 1 ? path.replace(/\/+$/u, '') : path
})
const currentAt = $derived(
  ((at: string | undefined): number => {
    if (at === undefined) return -1
    const exact = items.findIndex((item) => item.href === at)
    if (exact !== -1) return exact
    const page = pageOf(at)
    const origin = originOf(at)
    return items.findIndex((item) => {
      const itemOrigin = originOf(item.href)
      return pageOf(item.href) === page && (itemOrigin === undefined || itemOrigin === origin)
    })
  })(current),
)
const navigatesHere = $derived(
  (event: MouseEvent): boolean =>
    !event.defaultPrevented &&
    event.button === 0 &&
    !event.metaKey &&
    !event.ctrlKey &&
    !event.shiftKey &&
    !event.altKey,
)
const route = $derived((event: MouseEvent, href: string): void => {
  if (!listening.navigate || !navigatesHere(event)) return
  event.preventDefault()
  onNavigate?.(href)
})
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'SectionNav',
    element: () => root,
    state: () => ({
      current: items[currentAt]?.href ?? null,
      items: items
        .filter((item, at) => items.findIndex((other) => other.href === item.href) === at)
        .map((item) => ({ id: item.href, label: item.label })),
    }),
    actions: {
      choose: {
        argument: 'id',
        run: (value) =>
          agentPress(root?.querySelectorAll('a')[items.findIndex((item) => item.href === value)]),
      },
    },
  })
  release1 = () => {
    ran()
  }
}
watchEffect(effect1)
onDestroy(() => release1?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<nav bind:this={root} class={styles.nav} aria-label={label} data-member="section-nav"
    ><ul class={styles.list}
      >{#each items as item, index (`${index}:${item.href}`)
        }<li class={styles.item}
          ><a
            class={styles.link}
            href={item.href}
            aria-current={(index === currentAt) ? 'page' : undefined}
            onclick={(event) => { route(event, item.href) }}
            ><span class={styles.label}>{item.label}</span
          ></a
        ></li
      >{/each
    }</ul
  ></nav
>{/if
}{@render joined.end?.()}
